SELECT 
FROM plt_dynamic_form_template t

WHERE t.tenant_id = #{query.tenantId} AND t.deleted = b'0'

    AND t.template_name LIKE CONCAT('%', #{query.templateNameKeyword}, '%')


    AND t.category_code = #{query.categoryCode}


    AND t.availability_code = #{query.availabilityCode}


    AND t.current_published_revision_id IS NOT NULL

ORDER BY t.template_name ASC, t.id ASC
LIMIT #{query.limit} OFFSET #{query.offset}

SELECT COUNT(*) FROM plt_dynamic_form_template t WHERE t.tenant_id = #{query.tenantId} AND t.deleted = b'0'
AND t.template_name LIKE CONCAT('%', #{query.templateNameKeyword}, '%')
AND t.category_code = #{query.categoryCode}
AND t.availability_code = #{query.availabilityCode}
AND t.current_published_revision_id IS NOT NULL
